<?php
namespace Tests\Feature;
use App\Models\{Product,Release,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class AdminSecurityTest extends TestCase { use RefreshDatabase; public function test_viewer_cannot_mutate_admin_resources():void{$viewer=User::factory()->create(['role'=>'viewer','active'=>true]);$this->actingAs($viewer)->post('/customers',['name'=>'Denied','status'=>'active'])->assertForbidden();$this->assertDatabaseMissing('customers',['name'=>'Denied']);} public function test_admin_can_create_customer():void{$admin=User::factory()->create(['role'=>'admin','active'=>true]);$this->actingAs($admin)->post('/customers',['name'=>'Allowed','status'=>'active'])->assertRedirect(route('customers.index'));$this->assertDatabaseHas('customers',['name'=>'Allowed']);} public function test_published_package_metadata_is_immutable():void{$product=Product::create(['name'=>'Office','slug'=>'office','status'=>'active']);$release=Release::create(['product_id'=>$product->id,'version'=>'1.0.0','channel'=>'stable','status'=>'published','source_type'=>'manual','package_path'=>'packages/old.zip','package_sha256'=>str_repeat('a',64),'published_at'=>now()]);$this->expectException(\DomainException::class);$release->update(['package_path'=>'packages/replaced.zip']);} }
